// CSD_RATIONALE_BEGIN
// This strategy uses a two-phase approach: unconstrained and constrained.
// In the unconstrained phase, we generate tokens without considering grammar constraints,
// penalizing the closing token '>>' to encourage longer chains before '<<' triggers.
// Once '<<' is encountered, we enter the constrained phase where we enforce grammar constraints.
// We use the ConfidenceGatedStep method to ensure that we only hard-constrain when the model's
// top choice is grammar-invalid, allowing us to explore more diverse solutions.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    lm.GenerateLogits(prompt + generated);
    helpers.PenalizeTokenLogits(lm, [">>"], 5.0);
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
    }
  } else {
    var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
    generated := generated + [next];
    steps := steps + 1;
    if wasConstrained {
      currentConstrained := currentConstrained + [next];
      if Contains(next, ">>") { insideConstrained := false; }
    } else {
      insideConstrained := false;
    }
  }
}
cost := helpers.cost;

